4	/**
5	 * Plain (non-action) aggregation helpers for the visitor-analytics admin page.
6	 * These are read-only Prisma queries over the `Visit` table. Everything is
7	 * scoped to short recent windows and small `take` limits so the page stays
8	 * cheap even as the visit log grows.
9	 */
10	
11	const DAY = 86_400_000;
12	
13	/** IPs the admin has chosen to exclude from analytics (their own IP, office IP,
14	 *  a noisy bot) so the numbers reflect ACTUAL public traffic. Stored as a
15	 *  comma-separated setting. */
16	export async function excludedIps(): Promise<string[]> {
17	  const raw = (await getSetting("analytics_excluded_ips")) ?? "";
18	  return raw.split(",").map((s) => s.trim()).filter(Boolean);
19	}
20	
21	/** Prisma where-fragment dropping excluded IPs. Empty object when none are set,
22	 *  so it spreads harmlessly into any `where`. */
23	async function ipEx(): Promise<{ ip?: { notIn: string[] } }> {
24	  const e = await excludedIps();
25	  return e.length ? { ip: { notIn: e } } : {};
26	}
27	
28	/** Distinct client IPs seen in the last `minutes` — our "live visitors now" gauge. */
29	export async function liveVisitors(minutes = 5): Promise<number> {
30	  const since = new Date(Date.now() - minutes * 60_000);
31	  const rows = await db.visit.findMany({
32	    where: { createdAt: { gte: since }, ...(await ipEx()) },
33	    distinct: ["ip"],
34	    select: { ip: true },
35	  });
36	  return rows.length;
37	}
38	
39	/** Total page views since local midnight. */
40	export async function todayViews(): Promise<number> {
41	  const start = new Date();
42	  start.setHours(0, 0, 0, 0);
43	  return db.visit.count({ where: { createdAt: { gte: start }, ...(await ipEx()) } });
44	}
45	
46	/** Total page views in the trailing `days` window (default 7d). */
47	export async function viewsInWindow(days = 7): Promise<number> {
48	  const since = new Date(Date.now() - days * DAY);
49	  return db.visit.count({ where: { createdAt: { gte: since }, ...(await ipEx()) } });
50	}
51	
52	/** Distinct visitors (by IP) in the trailing `days` window. */
53	export async function uniqueVisitors(days = 7): Promise<number> {
54	  const since = new Date(Date.now() - days * DAY);
55	  const rows = await db.visit.findMany({
56	    where: { createdAt: { gte: since }, ...(await ipEx()) },
57	    distinct: ["ip"],
58	    select: { ip: true },
59	  });
60	  return rows.length;
61	}
62	
63	/** Reduce a raw referrer URL to a bare hostname for grouping/display. */
64	export function referrerHost(ref: string | null | undefined): string | null {
65	  if (!ref) return null;
66	  try {
67	    const h = new URL(ref).hostname.replace(/^www\./, "");
68	    return h || null;
69	  } catch {
70	    const trimmed = ref.trim();
71	    return trimmed ? trimmed.slice(0, 60) : null;
72	  }
73	}
74	
75	export type Counted = { label: string; count: number };
76	
77	/** Top external referrer hosts over the trailing `days` window. */
78	export async function topReferrers(days = 7, limit = 8): Promise<Counted[]> {
79	  const since = new Date(Date.now() - days * DAY);
80	  const rows = await db.visit.findMany({
81	    where: { createdAt: { gte: since }, referrer: { not: null }, ...(await ipEx()) },
82	    select: { referrer: true },
83	    take: 5000,
84	    orderBy: { createdAt: "desc" },
85	  });
86	  const tally = new Map<string, number>();
87	  for (const r of rows) {
88	    const host = referrerHost(r.referrer);
89	    if (!host) continue;
90	    tally.set(host, (tally.get(host) ?? 0) + 1);
91	  }
92	  return [...tally.entries()]
93	    .map(([label, count]) => ({ label, count }))
94	    .sort((a, b) => b.count - a.count)
95	    .slice(0, limit);
96	}
97	
98	/** Top countries among geocoded visits over the trailing `days` window. */
99	export async function topCountries(days = 30, limit = 8): Promise<Counted[]> {
100	  const since = new Date(Date.now() - days * DAY);
101	  const grp = await db.visit.groupBy({
102	    by: ["country"],
103	    where: { createdAt: { gte: since }, geocoded: true, country: { not: null }, ...(await ipEx()) },
104	    _count: { _all: true },
105	  });
106	  return grp
107	    .map((g) => ({ label: g.country as string, count: g._count._all }))
108	    .sort((a, b) => b.count - a.count)
109	    .slice(0, limit);
110	}
111	
112	/** Top cities among geocoded visits over the trailing `days` window. */
113	export async function topCities(days = 30, limit = 8): Promise<Counted[]> {
114	  const since = new Date(Date.now() - days * DAY);
115	  const rows = await db.visit.findMany({
116	    where: { createdAt: { gte: since }, geocoded: true, city: { not: null }, ...(await ipEx()) },
117	    select: { city: true, country: true },
118	    take: 5000,
119	    orderBy: { createdAt: "desc" },
120	  });
121	  const tally = new Map<string, number>();
122	  for (const r of rows) {
123	    const label = r.country ? `${r.city}, ${r.country}` : (r.city as string);
124	    tally.set(label, (tally.get(label) ?? 0) + 1);
125	  }
126	  return [...tally.entries()]
127	    .map(([label, count]) => ({ label, count }))
128	    .sort((a, b) => b.count - a.count)
129	    .slice(0, limit);
130	}
