10	/**
11	 * Manage the analytics IP exclude-list — the "hide my own traffic" control. The
12	 * list feeds lib/analytics.ts (ipEx) so every visitor stat drops these IPs, so
13	 * the dashboard shows ACTUAL public traffic. Admin-only (fleet-adjacent, gated
14	 * on the same "platform" area as the rest of the analytics tooling).
15	 */
16	
17	const KEY = "analytics_excluded_ips";
18	const IPV4 = /^\d{1,3}(\.\d{1,3}){3}$/;
19	const IPV6ish = /^[0-9a-fA-F:]{2,45}$/;
20	
21	function valid(ip: string): boolean {
22	  const a = ip.trim();
23	  return IPV4.test(a) || (a.includes(":") && IPV6ish.test(a));
24	}
25	
26	/** The admin's own current IP + the current exclude-list, for the panel. */
27	export async function analyticsExcludeState(): Promise<{ myIp: string; excluded: string[] }> {
28	  await requireArea("analytics");
29	  const myIp = clientIp(await headers());
30	  return { myIp, excluded: await excludedIps() };
31	}
