33	export async function addExcludedIp(ip: string): Promise<{ error?: string; ok?: boolean }> {
34	  await requireArea("analytics");
35	  const clean = String(ip ?? "").trim();
36	  if (!valid(clean)) return { error: "Enter a valid IPv4 or IPv6 address." };
37	  const cur = await excludedIps();
38	  if (!cur.includes(clean)) cur.push(clean);
39	  await setSetting(KEY, cur.slice(0, 100).join(","));
40	  revalidatePath("/admin/visitors");
41	  return { ok: true };
42	}
43	
44	export async function removeExcludedIp(ip: string): Promise<void> {
45	  await requireArea("analytics");
46	  const cur = (await excludedIps()).filter((x) => x !== ip);
47	  await setSetting(KEY, cur.join(","));
48	  revalidatePath("/admin/visitors");
49	}
