4	import { trustedClientIp } from "@/app/api/_lib/client-ip";
5	
6	export const runtime = "nodejs";
7	
8	/**
9	 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
10	 * in the marketing layout and the portal Shell. It records a single `Visit` row
11	 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
12	 *
13	 * The client IP is the PROXY-ATTESTED address (`trustedClientIp`); we never
14	 * trust a body-supplied IP, nor the first hop of `X-Forwarded-For` — nginx
15	 * appends to that header, so its first entry is caller-chosen. That mattered
16	 * twice here: it was the rate-limit key (so one header defeated the 60/min cap
17	 * on durable row insertion), and it is PERSISTED to `Visit.ip`, which is what
18	 * the admin visitors/analytics pages attribute traffic and abuse to. A forged
19	 * value poisoned both.
20	 *
21	 * Bots are dropped by a coarse UA check. The visit "kind" (marketing vs portal)
22	 * comes from a `?k=` query param the mounter sets.
23	 */
24	
25	const BOT_RE =
26	  /bot|crawl|spider|slurp|bingpreview|mediapartners|adsbot|facebookexternalhit|embedly|quora|pinterest|redditbot|whatsapp|telegrambot|discordbot|slackbot|semrush|ahrefs|mj12|dotbot|petalbot|yandex|baidu|duckduckbot|headless|phantomjs|python-requests|python-urllib|go-http|libwww|curl\/|wget\/|okhttp|axios\/|node-fetch|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|monitor|preview|scrapy/i;
27	
28	export async function POST(req: Request) {
29	  try {
30	    // Unauthenticated endpoint that writes a durable row per hit — throttle
31	    // per-IP to cap unbounded row insertion. Over the limit: silent no-op.
32	    const ip = trustedClientIp(req);
33	    const rl = checkRateLimit(`track:${ip}`, { max: 60, windowMs: 60_000 });
34	    if (!rl.ok) {
35	      return new NextResponse(null, { status: 204 });
36	    }
37	
38	    const url = new URL(req.url);
39	    const kindParam = url.searchParams.get("k");
40	    const kind = kindParam === "portal" ? "portal" : "marketing";
41	
42	    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
43	    // Silently accept but skip obvious bots and empty UAs.
44	    if (!ua || BOT_RE.test(ua)) {
45	      return NextResponse.json({ ok: true });
46	    }
47	
48	    const body = (await req.json().catch(() => ({}))) as {
49	      path?: unknown;
50	      referrer?: unknown;
51	    };
52	    const path =
53	      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
54	    let referrer =
55	      typeof body.referrer === "string" && body.referrer
56	        ? body.referrer.slice(0, 400)
57	        : null;
58	    // Drop same-origin referrers — they're just internal navigation noise.
59	    if (referrer) {
60	      try {
61	        if (new URL(referrer).host === url.host) referrer = null;
62	      } catch {
63	        /* keep opaque referrer strings as-is */
64	      }
65	    }
66	
67	    await db.visit.create({
68	      data: { ip, path, referrer, ua, kind },
69	    });
70	  } catch {
71	    // Never surface capture failures to the page.
72	  }
73	  return NextResponse.json({ ok: true });
74	}
